import { useEffect, useState } from 'react';
import apiService from '../services/api';
import {
  resolveEffectivePlanTier,
  type GatedFeature,
  planHasFeature,
} from '../utils/planEntitlements';
import type { PlanTier } from '../constants/pricingPlans';

interface BillingProfile {
  selectedPlanId?: string | null;
  status?: string;
  paidUntil?: string | null;
}

export function usePlanTier() {
  const [tier, setTier] = useState<PlanTier>('free');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let mounted = true;
    const load = async () => {
      try {
        const billingRes = (await apiService.getBillingStatus()) as {
          data?: { profile?: BillingProfile };
        };
        if (!mounted) return;
        const profile = billingRes?.data?.profile ?? null;
        setTier(resolveEffectivePlanTier(profile?.selectedPlanId, profile?.status, profile?.paidUntil));
      } catch {
        if (mounted) {
          setTier('free');
        }
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    };
    void load();
    return () => {
      mounted = false;
    };
  }, []);

  const hasFeature = (feature: GatedFeature) => planHasFeature(tier, feature);

  return { tier, loading, hasFeature };
}
